catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        g_form.setValue('course', '');
        g_form.setValue('instructor', '');
        g_form.setValue('date', '');
        return;
    }

    g_form.getReference('training', function(trainingGR) {
        g_form.setValue('course', trainingGR.getDisplayValue('x_221517_nowtrai_0_training_course'));
        g_form.setValue('instructor', trainingGR.getDisplayValue('x_221517_nowtrai_0_training_instructor'));
        g_form.setValue('date', trainingGR.x_221517_nowtrai_0_training_date);
    });

}
